<?php
require_once __DIR__ . '/config.php';require_admin();$pdo=db();
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$name=trim((string)($_POST['name']??''));$username=trim((string)($_POST['username']??''));$password=(string)($_POST['password']??'');$role=(string)($_POST['role']??'staff');if($name===''||!preg_match('/^[A-Za-z0-9_.-]{3,50}$/',$username)||strlen($password)<10||!in_array($role,['admin','staff'],true))flash('Isi nama, username 3-50 karakter (huruf/angka/._-), password minimal 10 karakter, dan role yang valid.','error');else try{$s=$pdo->prepare('INSERT INTO users(name,username,password_hash,role) VALUES(?,?,?,?)');$s->execute([$name,$username,password_hash($password,PASSWORD_DEFAULT),$role]);flash('Pengguna berhasil ditambahkan.');}catch(Throwable $e){flash('Gagal menambahkan pengguna. Username mungkin sudah digunakan.','error');}redirect('users.php');}
$rows=$pdo->query('SELECT id,name,username,role,created_at FROM users ORDER BY created_at DESC')->fetchAll();$pageTitle='Manajemen pengguna';require 'partials_header.php';?>
<section class="panel"><div class="panel-heading"><h2>Tambah pengguna</h2></div><form method="post" class="form-grid"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><div><label>Nama *</label><input name="name" required maxlength="100"></div><div><label>Username *</label><input name="username" required minlength="3" maxlength="50"></div><div><label>Password awal (min. 10 karakter) *</label><input type="password" name="password" required minlength="10" autocomplete="new-password"></div><div><label>Role *</label><select name="role"><option value="staff">Staff</option><option value="admin">Admin</option></select></div><div class="wide"><button class="btn primary">Tambah pengguna</button></div></form></section>
<section class="panel"><div class="panel-heading"><h2>Pengguna terdaftar</h2></div><div class="table-wrap"><table><thead><tr><th>Nama</th><th>Username</th><th>Role</th><th>Dibuat</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?= e($r['name']) ?></td><td><?= e($r['username']) ?></td><td><span class="badge"><?= e($r['role']) ?></span></td><td><?= e($r['created_at']) ?></td></tr><?php endforeach; ?></tbody></table></div></section><?php require 'partials_footer.php'; ?>
